function NotifPanel({notifs,onClose,onMarkRead}){const unread=notifs.filter(n=>!n.read).length;
return(<><div onClick={onClose} style={{position:'absolute',inset:0,background:'rgba(0,0,0,0.65)',zIndex:60,backdropFilter:'blur(3px)'}}/><div style={{position:'absolute',top:0,right:0,bottom:0,width:280,background:C.s0,borderLeft:`1px solid ${C.bdr}`,zIndex:70,display:'flex',flexDirection:'column'}}><div style={{padding:'14px 16px',borderBottom:`1px solid ${C.bdr}`,flexShrink:0}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><p style={{color:C.white,fontWeight:800,fontSize:15,margin:0}}>🔔 Notifications</p><p style={{color:unread>0?C.red:C.muted,fontSize:10,margin:'3px 0 0',fontWeight:700}}>{unread>0?`${unread} unread`:'All read'}</p></div><button onClick={onClose} style={{background:`${r(C.acc)}0.1)`,border:`1px solid ${C.bdr}`,borderRadius:10,width:34,height:34,cursor:'pointer',color:C.white,fontSize:16}}>✕</button></div></div><div style={{flex:1,overflowY:'auto',padding:'10px 12px',scrollbarWidth:'none'}}>{notifs.map(n=>(<div key={n.id} onClick={()=>onMarkRead(n.id)} style={{padding:'10px 12px',borderRadius:12,marginBottom:6,cursor:'pointer',background:n.read?'transparent':C.s1,border:`1px solid ${n.read?'transparent':`${r(n.c||C.acc)}0.22)`}`}}><div style={{display:'flex',gap:8,alignItems:'flex-start'}}><span style={{fontSize:18,flexShrink:0}}>{n.icon}</span><div style={{flex:1}}><p style={{fontSize:12,color:n.read?C.muted:C.white,fontWeight:n.read?400:600,margin:'0 0 3px',lineHeight:1.4}}>{n.msg}</p><p style={{fontSize:10,color:C.mut2,margin:0}}>{n.time}</p></div>{!n.read&&<div style={{width:7,height:7,borderRadius:'50%',background:n.c||C.acc,flexShrink:0,marginTop:4}}/>}</div></div>))}</div><div style={{padding:'10px 12px',borderTop:`1px solid ${C.bdr}`,flexShrink:0,display:'flex',gap:8}}><OBtn ch="Mark All Read" color={C.muted} onClick={()=>notifs.forEach(n=>onMarkRead(n.id))} style={{flex:1,textAlign:'center',fontSize:11}}/><OBtn ch="View All" color={C.acc} style={{flex:1,textAlign:'center',fontSize:11}}/></div></div></>);}

/* ─── SIDEBAR ─── */
const getNavForRole=role=>(['ceo','gm'].includes(role))?NAV:role==='finance'?NAV.filter(n=>['dashboard','finance','expenses','reports','settings'].includes(n.id)):role==='branch'?NAV.filter(n=>n.id!=='website'):role==='staff'?NAV.filter(n=>['dashboard','pos','supermarket','quotes','inventory','customers','services','tyreFinder','layby'].includes(n.id)):role==='fuel'?NAV.filter(n=>['dashboard','fuel','cashup','expenses'].includes(n.id)):NAV;

const NavList=({items,current,onNav,pendingApprovals})=>(<div style={{flex:1,overflowY:'auto',padding:'10px 8px',scrollbarWidth:'none'}}><p style={{color:C.mut2,fontSize:9,fontWeight:800,letterSpacing:'0.14em',padding:'4px 8px 8px',margin:0}}>MODULES</p>{items.map(item=>{const active=current===item.id;const badge=item.id==='approvals'?pendingApprovals:0;return(<button key={item.id} onClick={()=>onNav(item.id)} style={{width:'100%',display:'flex',alignItems:'center',gap:12,padding:'10px 12px',borderRadius:12,marginBottom:2,cursor:'pointer',textAlign:'left',background:active?`${r(C.acc)}0.15)`:'transparent',border:`1px solid ${active?`${r(C.acc)}0.3)`:'transparent'}`}}><span style={{fontSize:18}}>{item.icon}</span><span style={{fontSize:13,fontWeight:active?700:500,color:active?C.white:C.muted,flex:1}}>{item.label}</span>{badge>0&&<span style={{background:C.red,color:C.white,fontSize:9,fontWeight:900,minWidth:18,height:18,borderRadius:9,display:'flex',alignItems:'center',justifyContent:'center',padding:'0 4px'}}>{badge}</span>}{active&&!badge&&<span style={{width:7,height:7,borderRadius:'50%',background:C.acc}}/>}</button>);})}</div>);

function Sidebar({current,onNav,onClose,role,pendingApprovals}){
const acc=getNavForRole(role);
return(<><div onClick={onClose} style={{position:'absolute',inset:0,background:'rgba(0,0,0,0.65)',zIndex:40,backdropFilter:'blur(3px)'}}/><div style={{position:'absolute',top:0,left:0,bottom:0,width:252,background:C.s0,borderRight:`1px solid ${C.bdr}`,zIndex:50,display:'flex',flexDirection:'column',overflow:'hidden'}}><div style={{padding:'16px 14px',borderBottom:`1px solid ${C.bdr}`,flexShrink:0,background:'linear-gradient(135deg,rgba(21,101,192,0.14),rgba(124,0,0,0.08))'}}><div style={{display:'flex',alignItems:'center',gap:10}}><div style={{width:44,height:44,borderRadius:14,background:'linear-gradient(135deg,#1565C0,#7C0000)',display:'flex',alignItems:'center',justifyContent:'center',fontWeight:900,color:C.white,fontSize:22}}>A</div><div><p style={{color:C.white,fontWeight:900,fontSize:17,letterSpacing:'0.18em',margin:0}}>ADMABS</p><p style={{color:C.muted,fontSize:9,letterSpacing:'0.12em',margin:0}}>BUSINESS PLATFORM</p></div></div></div><NavList items={acc} current={current} onNav={id=>{onNav(id);onClose();}} pendingApprovals={pendingApprovals}/><div style={{padding:'10px 14px',borderTop:`1px solid ${C.bdr}`,flexShrink:0}}><button style={{width:'100%',padding:'9px 12px',borderRadius:12,cursor:'pointer',background:`${r(C.red)}0.08)`,border:`1px solid ${r(C.red)}0.25)`,color:C.red,fontSize:12,fontWeight:700}}>🚪 Sign Out</button></div></div></>);}

/* ─── DESKTOP NAV (docked, shown ≥880px via CSS) ─── */
function DesktopNav({current,onNav,role,pendingApprovals}){
const acc=getNavForRole(role);
return(<div className="admabs-desktop-nav" style={{display:'none',flexDirection:'column',width:264,flexShrink:0,background:C.s0,borderRight:`1px solid ${C.bdr}`,overflow:'hidden'}}><div style={{padding:'18px 16px',borderBottom:`1px solid ${C.bdr}`,flexShrink:0,background:'linear-gradient(135deg,rgba(21,101,192,0.14),rgba(124,0,0,0.08))'}}><div style={{display:'flex',alignItems:'center',gap:10}}><div style={{width:44,height:44,borderRadius:14,background:'linear-gradient(135deg,#1565C0,#7C0000)',display:'flex',alignItems:'center',justifyContent:'center',fontWeight:900,color:C.white,fontSize:22}}>A</div><div><p style={{color:C.white,fontWeight:900,fontSize:17,letterSpacing:'0.18em',margin:0}}>ADMABS</p><p style={{color:C.muted,fontSize:9,letterSpacing:'0.12em',margin:0}}>BUSINESS PLATFORM</p></div></div></div><NavList items={acc} current={current} onNav={onNav} pendingApprovals={pendingApprovals}/><div style={{padding:'10px 14px',borderTop:`1px solid ${C.bdr}`,flexShrink:0}}><button style={{width:'100%',padding:'9px 12px',borderRadius:12,cursor:'pointer',background:`${r(C.red)}0.08)`,border:`1px solid ${r(C.red)}0.25)`,color:C.red,fontSize:12,fontWeight:700}}>🚪 Sign Out</button></div></div>);}

/* ─── TOP BAR ─── */
function TopBar({role,onMenu,onNotif,unread,pendingApprovals,onApprovals}){const RI={ceo:{i:'👑',c:C.gold},gm:{i:'🏢',c:C.acc},branch:{i:'🏪',c:C.green},finance:{i:'💰',c:C.purp},staff:{i:'🛒',c:C.red},fuel:{i:'⛽',c:C.orange}};const info=RI[role]||RI['gm'];
return(<div style={{background:C.s0,borderBottom:`1px solid ${C.bdr}`,padding:'10px 14px',display:'flex',alignItems:'center',gap:10,flexShrink:0}}><button className="admabs-hamburger-btn" onClick={onMenu} style={{background:`${r(C.acc)}0.12)`,border:`1px solid ${C.bdr}`,borderRadius:10,width:36,height:36,cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',fontSize:18,color:C.white}}>☰</button><div style={{display:'flex',alignItems:'center',gap:8,flex:1}}><div style={{width:34,height:34,borderRadius:10,background:'linear-gradient(135deg,#1565C0,#7C0000)',display:'flex',alignItems:'center',justifyContent:'center',fontWeight:900,color:C.white,fontSize:16}}>A</div><div><p style={{color:C.white,fontWeight:800,fontSize:14,margin:0}}>ADMABS</p><p style={{color:C.muted,fontSize:9,margin:0}}>Integrated Business Platform</p></div></div>{pendingApprovals>0&&<button onClick={onApprovals} style={{background:`${r(C.red)}0.1)`,border:`1px solid ${r(C.red)}0.35)`,borderRadius:10,height:36,cursor:'pointer',display:'flex',alignItems:'center',gap:4,padding:'0 10px',color:C.red,fontWeight:700,fontSize:12}}>✅ {pendingApprovals}</button>}<button onClick={onNotif} style={{position:'relative',background:`${r(C.acc)}0.1)`,border:`1px solid ${C.bdr}`,borderRadius:10,width:36,height:36,cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',fontSize:16}}>🔔{unread>0&&<div style={{position:'absolute',top:7,right:7,width:8,height:8,borderRadius:'50%',background:C.red}}/>}</button><div style={{width:36,height:36,borderRadius:10,fontSize:18,background:`${r(info.c)}0.15)`,border:`2px solid ${r(info.c)}0.45)`,display:'flex',alignItems:'center',justifyContent:'center'}}>{info.i}</div></div>);}

/* ─── APP ─── */
export default function App(){
const [phase,setPhase]=useState('splash');const [role,setRole]=useState(null);const [screen,setScreen]=useState('dashboard');const [sidebar,setSidebar]=useState(false);const [notifOpen,setNotifOpen]=useState(false);const [notifs,setNotifs]=useState(NOTIFS_D);const [pendingApprovals,setPendingApprovals]=useState(0);
const login=r=>{setRole(r);setPhase('app');setScreen('dashboard');};
const markRead=id=>setNotifs(ns=>ns.map(n=>n.id===id?{...n,read:true}:n));
const refreshApprovalsCount=()=>{api.approvals().then(list=>setPendingApprovals(list.filter(a=>a.status==='pending').length)).catch(()=>{});};
useEffect(()=>{if(phase==='app')refreshApprovalsCount();},[phase]);
const unread=notifs.filter(n=>!n.read).length;
const TITLES={dashboard:'Dashboard',pos:'Point of Sale',supermarket:'Supermarket POS',quotes:'Quotations',inventory:'Inventory',fuel:'Fuel Station',finance:'Finance & Accounting',procurement:'Procurement',customers:'Customers & Fleet',loyalty:'Loyalty Programme',services:'Services & Warranty',hr:'HR & Payroll',cashup:'Cash-up & Closing',layby:'Layby Management',tyreFinder:'Tyre Finder',expenses:'Expenses',marketing:'Marketing & CRM',assets:'Asset Register',pricelists:'Prices & Promos',approvals:'Approvals',reports:'Reports & Analytics',staff:'Staff Management',website:'Website & Online Store',settings:'System Settings'};
const ROLE_LABELS={ceo:'CEO / Director',gm:'General Manager',branch:'Branch Manager · Harare Main',finance:'Finance Manager',staff:'Sales Attendant · Harare',fuel:'Fuel Attendant · Fuel Station'};
const renderScreen=()=>{switch(screen){case'dashboard':return<DashScreen onNav={setScreen}/>;case'pos':return<POSScreen/>;case'supermarket':return<SupermarketScreen/>;case'quotes':return<QuotationsScreen/>;case'inventory':return<InventoryScreen/>;case'fuel':return<FuelScreen/>;case'finance':return<FinanceScreen/>;case'procurement':return<ProcurementScreen/>;case'customers':return<CustomersScreen/>;case'loyalty':return<LoyaltyScreen/>;case'services':return<ServicesScreen/>;case'hr':return<HRScreen/>;case'cashup':return<CashUpScreen/>;case'layby':return<LaybyScreen/>;case'tyreFinder':return<TyreFinderScreen/>;case'expenses':return<ExpensesScreen/>;case'marketing':return<MarketingScreen/>;case'assets':return<AssetsScreen/>;case'pricelists':return<PriceListScreen/>;case'approvals':return<ApprovalsScreen onChanged={refreshApprovalsCount}/>;case'reports':return<ReportsScreen/>;case'staff':return<StaffScreen/>;case'website':return<WebsiteScreen/>;case'settings':return<SettingsScreen/>;default:return<DashScreen onNav={setScreen}/>;
}};
return(<div style={{position:'fixed',inset:0,background:'#000',display:'flex',alignItems:'stretch',justifyContent:'center',fontFamily:'"Segoe UI",system-ui,sans-serif'}}><div className="admabs-shell" style={{width:'100%',maxWidth:430,position:'relative',overflow:'hidden',background:C.bg,display:'flex',flexDirection:'column'}}>{phase==='splash'&&<Splash onDone={()=>setPhase('login')}/>}{phase==='login'&&<Login onLogin={login}/>}{phase==='app'&&(<div className="admabs-app-row" style={{display:'flex',flex:1,minHeight:0}}><DesktopNav current={screen} onNav={setScreen} role={role} pendingApprovals={pendingApprovals}/><div className="admabs-main-col" style={{display:'flex',flexDirection:'column',flex:1,minWidth:0}}><TopBar role={role} onMenu={()=>setSidebar(true)} onNotif={()=>{setSidebar(false);setNotifOpen(o=>!o);}} unread={unread} pendingApprovals={pendingApprovals} onApprovals={()=>setScreen('approvals')}/><div style={{background:'linear-gradient(90deg,rgba(21,101,192,0.1),rgba(185,28,28,0.04))',borderBottom:`1px solid ${C.bdr}`,padding:'6px 14px',display:'flex',alignItems:'center',gap:6,flexShrink:0}}><span style={{fontSize:10,color:C.muted,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{ROLE_LABELS[role]||'User'}</span><span style={{color:C.mut2,fontSize:12}}>›</span><span style={{fontSize:11,color:C.acc,fontWeight:700,whiteSpace:'nowrap'}}>{TITLES[screen]||screen}</span></div><div className="admabs-content" style={{flex:1,overflowY:'auto',scrollbarWidth:'none'}}>{renderScreen()}</div><div className="admabs-bottom-nav" style={{background:C.s0,borderTop:`1px solid ${C.bdr}`,flexShrink:0,display:'flex',padding:'6px 8px 10px'}}>{[{id:'dashboard',i:'📊',l:'Home'},{id:'tyreFinder',i:'🔍',l:'Finder'},{id:'pos',i:'🛒',l:'POS'},{id:'cashup',i:'🏧',l:'Cash-up'},{id:'approvals',i:'✅',l:'Approvals',badge:pendingApprovals}].map(item=>{const active=screen===item.id;return(<button key={item.id} onClick={()=>setScreen(item.id)} style={{flex:1,display:'flex',flexDirection:'column',alignItems:'center',gap:2,padding:'4px 0',background:'transparent',border:'none',cursor:'pointer',position:'relative'}}>{active&&<div style={{position:'absolute',top:-6,left:'50%',transform:'translateX(-50%)',width:30,height:2,background:C.acc,borderRadius:'0 0 2px 2px'}}/>}<div style={{position:'relative'}}><span style={{fontSize:20}}>{item.i}</span>{item.badge>0&&<span style={{position:'absolute',top:-3,right:-6,background:C.red,color:C.white,fontSize:8,fontWeight:900,minWidth:14,height:14,borderRadius:7,display:'flex',alignItems:'center',justifyContent:'center',padding:'0 2px'}}>{item.badge}</span>}</div><span style={{fontSize:9,fontWeight:active?800:500,letterSpacing:'0.05em',color:active?C.acc:C.muted}}>{item.l.toUpperCase()}</span></button>);})}</div></div>{sidebar&&<Sidebar current={screen} onNav={setScreen} onClose={()=>setSidebar(false)} role={role} pendingApprovals={pendingApprovals}/>}{notifOpen&&<NotifPanel notifs={notifs} onClose={()=>setNotifOpen(false)} onMarkRead={markRead}/>}</div>)}</div></div>);}
